create extension if not exists pgcrypto;
create type app_role as enum ('customer','staff','admin','owner');
create type row_status as enum ('draft','active','live','hidden','seasonal','unavailable','paused','cancelled','completed');
create or replace function set_updated_at() returns trigger language plpgsql as $$ begin new.updated_at=now(); return new; end $$;
create table profiles(id uuid primary key references auth.users(id) on delete cascade,email text unique,full_name text,role app_role default 'customer',created_at timestamptz default now(),updated_at timestamptz default now());
create table admin_users(id uuid primary key default gen_random_uuid(),email text unique not null,role app_role not null check(role in('staff','admin','owner')),status text default 'active',created_at timestamptz default now(),updated_at timestamptz default now());
create table admin_settings(id uuid primary key default gen_random_uuid(),key text unique not null,value jsonb not null,created_at timestamptz default now(),updated_at timestamptz default now());
create table addresses(id uuid primary key default gen_random_uuid(),user_id uuid references profiles(id),full_address text not null,latitude numeric,longitude numeric,google_place_id text,distance_from_kitchen_km numeric,matched_delivery_zone_id uuid,delivery_fee numeric default 0,is_serviceable boolean default false,created_at timestamptz default now(),updated_at timestamptz default now());
create table dish_categories(id uuid primary key default gen_random_uuid(),name text unique not null,sort_order int default 0,status text default 'active',created_at timestamptz default now(),updated_at timestamptz default now());
create table dishes(id uuid primary key default gen_random_uuid(),category_id uuid references dish_categories(id),name text not null,meal_type text,image_url text,image_storage_path text,image_alt_text text,price numeric,status text default 'draft',calories numeric,protein_g numeric,carbohydrates_g numeric,fats_g numeric,fiber_g numeric,description text,created_at timestamptz default now(),updated_at timestamptz default now());
create table plans(id uuid primary key default gen_random_uuid(),plan_key text unique,name text not null,status text default 'active',description text,created_at timestamptz default now(),updated_at timestamptz default now());
create table plan_variants(id uuid primary key default gen_random_uuid(),plan_id uuid references plans(id) on delete cascade,variant_key text,name text,duration_days int,meals_per_day int,monthly_price numeric,weekly_price numeric,status text default 'active',created_at timestamptz default now(),updated_at timestamptz default now());
create table plan_aliases(id uuid primary key default gen_random_uuid(),alias text unique not null,plan_display_name text not null,variant_name text,created_at timestamptz default now(),updated_at timestamptz default now());
create table plan_day_menus(id uuid primary key default gen_random_uuid(),plan_id uuid references plans(id),plan_display_name text,cycle_week int check(cycle_week between 1 and 4),service_day int check(service_day between 1 and 24),component_1 text,component_2 text,component_3 text,component_4 text,component_5 text,calories numeric,protein_g numeric,carbohydrates_g numeric,fats_g numeric,fiber_g numeric,status text default 'draft',created_at timestamptz default now(),updated_at timestamptz default now(),unique(plan_display_name,service_day));
create table delivery_zones(id uuid primary key default gen_random_uuid(),zone_id text unique,zone_name text,status text default 'active',priority int default 100,min_order numeric default 0,delivery_fee numeric default 0,eta_min int,eta_max int,polygon_geojson jsonb,radius_km numeric,notes text,created_at timestamptz default now(),updated_at timestamptz default now());
alter table addresses add constraint addresses_zone_fk foreign key(matched_delivery_zone_id) references delivery_zones(id);
create table csv_import_jobs(id uuid primary key default gen_random_uuid(),dataset text not null,mode text not null,status text not null,valid_count int default 0,warning_count int default 0,error_count int default 0,created_by uuid references profiles(id),created_at timestamptz default now(),updated_at timestamptz default now());
create table csv_import_rows(id uuid primary key default gen_random_uuid(),job_id uuid references csv_import_jobs(id) on delete cascade,row_number int,raw_data jsonb,normalized_data jsonb,warnings jsonb,errors jsonb,created_at timestamptz default now(),updated_at timestamptz default now());
create table menu_snapshots(id uuid primary key default gen_random_uuid(),reason text,type text,created_by uuid references profiles(id),created_at timestamptz default now(),updated_at timestamptz default now());
create table menu_snapshot_items(id uuid primary key default gen_random_uuid(),snapshot_id uuid references menu_snapshots(id) on delete cascade,menu_row jsonb not null,created_at timestamptz default now(),updated_at timestamptz default now());
create table admin_audit_logs(id uuid primary key default gen_random_uuid(),actor_id uuid references profiles(id),action text not null,target_table text,target_id uuid,metadata jsonb default '{}',created_at timestamptz default now());
create table subscriptions(id uuid primary key default gen_random_uuid(),user_id uuid references profiles(id),plan_id uuid references plans(id),address_id uuid references addresses(id),start_date date not null,status text default 'active',created_at timestamptz default now(),updated_at timestamptz default now());
create table subscription_deliveries(id uuid primary key default gen_random_uuid(),subscription_id uuid references subscriptions(id) on delete cascade,delivery_date date not null check(extract(dow from delivery_date)<>0),meal_slot text,item_name text,status text default 'scheduled',created_at timestamptz default now(),updated_at timestamptz default now());
create table orders(id uuid primary key default gen_random_uuid(),user_id uuid references profiles(id),address_id uuid references addresses(id),delivery_date date not null check(extract(dow from delivery_date)<>0),status text default 'draft',created_at timestamptz default now(),updated_at timestamptz default now());
create table order_items(id uuid primary key default gen_random_uuid(),order_id uuid references orders(id) on delete cascade,dish_id uuid references dishes(id),item_name text,quantity int default 1,unit_price numeric default 0,created_at timestamptz default now(),updated_at timestamptz default now());
create table payments(id uuid primary key default gen_random_uuid(),user_id uuid references profiles(id),order_id uuid references orders(id),subscription_id uuid references subscriptions(id),provider text default 'razorpay',amount numeric not null,status text default 'pending',provider_payment_id text,created_at timestamptz default now(),updated_at timestamptz default now());
create table production_manifests(id uuid primary key default gen_random_uuid(),date date not null,meal_slot text,item_name text,subscription_quantity int default 0,preorder_quantity int default 0,addon_quantity int default 0,total_quantity int default 0,zone_split jsonb default '{}',status text default 'draft',created_at timestamptz default now(),updated_at timestamptz default now());
create table pause_requests(id uuid primary key default gen_random_uuid(),subscription_delivery_id uuid references subscription_deliveries(id),requested_by uuid references profiles(id),status text default 'pending',created_at timestamptz default now(),updated_at timestamptz default now());
create table swap_requests(id uuid primary key default gen_random_uuid(),subscription_delivery_id uuid references subscription_deliveries(id),requested_by uuid references profiles(id),requested_item text,status text default 'pending',created_at timestamptz default now(),updated_at timestamptz default now());
create table delivery_status_logs(id uuid primary key default gen_random_uuid(),subscription_delivery_id uuid references subscription_deliveries(id),order_id uuid references orders(id),status text,notes text,created_at timestamptz default now(),updated_at timestamptz default now());
